#include <map>
#include <iostream>

int main() {
    std::map<int, char> m;
    std::multimap<int, char> mm;

    // Map: Second insertion fails, value 'A' remains
    m.insert({1, 'A'});
    m.insert({1, 'B'}); 
    std::cout << "Map size: " << m.size() << ", Value: " << m.at(1) << std::endl;

    // Multimap: Both insertions succeed
    mm.insert({1, 'A'});
    mm.insert({1, 'B'});
    std::cout << "Multimap size: " << mm.size() << std::endl;

    // Use equal_range for multimap lookup
    auto range = mm.equal_range(1);
    // range.first != range.second is true
}
